const out = [];
for (const it of $input.all()) {
  const v = it.json;
  try {
    const u = new URL(/^https?:\/\//i.test(v.website) ? v.website : 'https://' + v.website);
    const domain = u.hostname.replace(/^www\./i, '').toLowerCase();
    if (!domain.includes('.')) continue;
    out.push({ json: { vendor_id: v.id, legal_name: v.legal_name, domain } });
  } catch (e) { /* URL inválida: se ignora */ }
}
return out;

const LOOKBACK_DAYS = Number($env.CT_LOOKBACK_DAYS || 3);
const cutoff = Date.now() - LOOKBACK_DAYS * 86400000;
const SUSPICIOUS = /(^|\.)(dev|test|stage|staging|uat|admin|vpn|internal|jenkins|git|gitlab|vault)(\d*)\./i;
const toTs = s => new Date(/Z$|[+-]\d\d:?\d\d$/.test(s) ? s : s + 'Z').getTime();
const items = $input.all();
const out = [];
let failed = 0, ok = 0;
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const v = $('Extract Domain').itemMatching(i).json;
  if (!resp || resp.statusCode !== 200 || !Array.isArray(resp.body)) { failed++; continue; }
  ok++;
  const seen = new Set();
  const recent = resp.body.filter(c => c.entry_timestamp && toTs(c.entry_timestamp) >= cutoff)
                          .filter(c => !seen.has(c.id) && seen.add(c.id)).slice(0, 25);
  for (const c of recent) {
    const names = [...new Set(String(c.name_value || '').split('\n').map(s => s.trim()).filter(Boolean))];
    const suspicious = names.filter(n => SUSPICIOUS.test(n + '.'));
    const issuer = (String(c.issuer_name || '').match(/O=([^,]+)/) || [])[1] || c.issuer_name || 'n/a';
    out.push({ json: {
      kind: 'finding', vendor_id: v.vendor_id, source: 'ct_log', source_ref: 'ct:' + c.id,
      title: ('Nuevo certificado emitido para ' + (c.common_name || v.domain) + ' (' + issuer + ')').slice(0, 300),
      description: 'Dominios: ' + names.slice(0, 20).join(', ') +
        (suspicious.length ? ' · Posibles hosts no productivos/administrativos: ' + suspicious.slice(0, 10).join(', ') : ''),
      severity: suspicious.length ? 'medium' : 'low',
      evidence: { crtsh_id: c.id, serial: c.serial_number, issuer: c.issuer_name, names: names.slice(0, 50),
                  not_before: c.not_before, not_after: c.not_after, logged_at: c.entry_timestamp }
    }});
  }
}
const findings = out.length;
out.push({ json: { kind: 'summary', job_type: 'ct_log', interval_min: 1440,
  status: failed === 0 ? 'ok' : (ok === 0 ? 'error' : 'partial'),
  meta: { domains: items.length, ok, failed, findings, lookback_days: LOOKBACK_DAYS } } });
return out;
